/*
 * @file  init_clock.c
 * @brief SystemInit, clock setup and delays for Espressif ESP32-C6 MCUs.
 *        Generated by scripts/espressif_mcus.py - do not edit, change the generator instead.
 *
 * SystemInit:
 *   1. Super watchdog auto-feed and RTC / timer group watchdogs off (the ROM bootloader leaves them running).
 *   2. CPU clock from the NECTO clock configuration (VALUE_* in core_header.h): the selected source/divider is
 *      turned into the CPU frequency and set by the ESP-IDF clock driver (rtc_clk_cpu_freq_set_config), which
 *      powers and calibrates the PLL and switches in the order Espressif uses.
 *   3. CPU cycle counter used by the delays.
 * The ESP-IDF sources below (thirdparty/, Apache-2.0) are compiled as part of this file.
 */

#include "thirdparty/sdkconfig.h"
#include "core_header.h"
#include "thirdparty/rtc_clk.c"
#include "thirdparty/wdt_hal_iram.c"
#include "thirdparty/regi2c_impl.c"

/* Failed ESP-IDF asserts stop here instead of printing through stdio. */
__attribute__((weak)) void __assert_func( const char *file, int line, const char *func, const char *expr )
{ (void)file; (void)line; (void)func; (void)expr; while ( 1 ); }

/* ESP RISC-V cores without mcycle count CPU cycles in the custom PCCR CSR (0x7E2) once enabled. */
static inline void cycle_counter_init( void ) { __asm__ volatile( "csrwi 0x7E0, 1\n csrwi 0x7E1, 1" ); }
static inline uint32_t cycle_counter( void ) { uint32_t v; __asm__ volatile( "csrr %0, 0x7E2" : "=r"( v ) ); return v; }

/* CPU frequency (MHz) selected by the NECTO clock configuration */
static uint32_t cpu_freq_mhz_from_config( void )
{
    if ( ( ( VALUE_PCR_SYSCLK_CONF & 0x00030000UL ) == 0x00000000UL ) ) {
        return 40; /* XTAL 40 MHz */
    }
    if ( ( ( VALUE_PCR_SYSCLK_CONF & 0x00030000UL ) == 0x00010000UL ) && ( ( VALUE_PCR_CPU_FREQ_CONF & 0x0000FF00UL ) == 0x00000100UL ) && ( ( VALUE_PCR_CPU_FREQ_CONF & 0x00010000UL ) == 0x00000000UL ) ) {
        return 80; /* PLL 480 MHz / 6 = 80 MHz */
    }
    if ( ( ( VALUE_PCR_SYSCLK_CONF & 0x00030000UL ) == 0x00010000UL ) && ( ( VALUE_PCR_CPU_FREQ_CONF & 0x0000FF00UL ) == 0x00000000UL ) && ( ( VALUE_PCR_CPU_FREQ_CONF & 0x00010000UL ) == 0x00010000UL ) ) {
        return 120; /* PLL 480 MHz / 4 = 120 MHz */
    }
    if ( ( ( VALUE_PCR_SYSCLK_CONF & 0x00030000UL ) == 0x00010000UL ) && ( ( VALUE_PCR_CPU_FREQ_CONF & 0x0000FF00UL ) == 0x00000000UL ) && ( ( VALUE_PCR_CPU_FREQ_CONF & 0x00010000UL ) == 0x00000000UL ) ) {
        return 160; /* PLL 480 MHz / 3 = 160 MHz */
    }
    return 160;
}

void SystemInit( void )
{
    /* 1. Watchdogs */
    REG_WRITE( LP_WDT_SWD_WPROTECT_REG, LP_WDT_SWD_WKEY_VALUE );
    REG_SET_BIT( LP_WDT_SWD_CONFIG_REG, LP_WDT_SWD_AUTO_FEED_EN );
    REG_WRITE( LP_WDT_SWD_WPROTECT_REG, 0 );

    wdt_hal_context_t rwdt = RWDT_HAL_CONTEXT_DEFAULT();
    wdt_hal_write_protect_disable( &rwdt );
    wdt_hal_set_flashboot_en( &rwdt, false );
    wdt_hal_disable( &rwdt );
    wdt_hal_write_protect_enable( &rwdt );

    wdt_hal_context_t mwdt0 = { .inst = WDT_MWDT0, .mwdt_dev = &TIMERG0 };
    wdt_hal_write_protect_disable( &mwdt0 );
    wdt_hal_set_flashboot_en( &mwdt0, false );
    wdt_hal_disable( &mwdt0 );
    wdt_hal_write_protect_enable( &mwdt0 );
#if SOC_MODULE_ATTR( TIMG, INST_NUM ) > 1 || defined( DR_REG_TIMERGROUP1_BASE ) || defined( DR_REG_TIMG1_BASE )
    wdt_hal_context_t mwdt1 = { .inst = WDT_MWDT1, .mwdt_dev = &TIMERG1 };
    wdt_hal_write_protect_disable( &mwdt1 );
    wdt_hal_set_flashboot_en( &mwdt1, false );
    wdt_hal_disable( &mwdt1 );
    wdt_hal_write_protect_enable( &mwdt1 );
#endif

    /* 2. CPU clock */
    rtc_cpu_freq_config_t cpu;
    if ( rtc_clk_cpu_freq_mhz_to_config( cpu_freq_mhz_from_config(), &cpu ) ) {
        rtc_clk_cpu_freq_set_config( &cpu );
    }

    /* 3. Cycle counter for the delays */
    cycle_counter_init();
}

/* Delays: busy wait on the CPU cycle counter, FOSC_KHZ_VALUE is the CPU clock. */
static void delay_cycles( uint32_t cycles )
{
    uint32_t start = cycle_counter();
    while ( ( uint32_t )( cycle_counter() - start ) < cycles );
}

void __attribute__( ( noinline ) ) Delay_Cyc( uint32_t cycles_div_by_10 )
{
    while ( cycles_div_by_10-- ) {
        delay_cycles( 10 );
    }
}

void __attribute__( ( noinline ) ) Delay_us( uint32_t time_us )
{
    const uint32_t per_us = FOSC_KHZ_VALUE / 1000UL;
    while ( time_us > 1000UL ) {
        delay_cycles( 1000UL * per_us );
        time_us -= 1000UL;
    }
    delay_cycles( time_us * per_us );
}

void __attribute__( ( noinline ) ) Delay_ms( uint32_t time_ms )
{
    while ( time_ms-- ) {
        Delay_us( 1000UL );
    }
}

void __attribute__( ( noinline ) ) Delay_Advanced_ms( uint32_t time_ms, uint32_t current_fosc_khz )
{
    while ( time_ms-- ) {
        delay_cycles( current_fosc_khz );
    }
}

void Delay_1us() { Delay_us( 1 ); }
void Delay_5us() { Delay_us( 5 ); }
void Delay_6us() { Delay_us( 6 ); }
void Delay_9us() { Delay_us( 9 ); }
void Delay_10us() { Delay_us( 10 ); }
void Delay_22us() { Delay_us( 22 ); }
void Delay_50us() { Delay_us( 50 ); }
void Delay_55us() { Delay_us( 55 ); }
void Delay_60us() { Delay_us( 60 ); }
void Delay_64us() { Delay_us( 64 ); }
void Delay_70us() { Delay_us( 70 ); }
void Delay_80us() { Delay_us( 80 ); }
void Delay_410us() { Delay_us( 410 ); }
void Delay_480us() { Delay_us( 480 ); }
void Delay_500us() { Delay_us( 500 ); }
void Delay_5500us() { Delay_us( 5500 ); }
void Delay_1ms() { Delay_ms( 1 ); }
void Delay_5ms() { Delay_ms( 5 ); }
void Delay_8ms() { Delay_ms( 8 ); }
